// На каждую накладную — один транзакционный T-SQL батч (задача 004):
// DELETE старой версии по file_name (каскад сносит позиции; устойчиво к
// смене id при переобработке — решение владельца: delete+insert),
// затем INSERT шапки и позиций. Идемпотентно: повтор того же батча
// даёт тот же результат.
const q = v => v == null ? 'NULL' : "N'" + String(v).replace(/'/g, "''") + "'";
const num = v => (v == null || v === '' || isNaN(Number(v))) ? 'NULL' : String(Number(v));
const out = [];
for (const item of $input.all()) {
  const inv = item.json;
  const items = inv.items || [];
  if (!items.length) continue;
  const vals = items.map(ii =>
    `(${ii.id}, ${inv.invoice_id}, ${ii.line_no}, ${q(ii.item_name)}, ${q(ii.unit)}, ${num(ii.quantity)}, ${num(ii.price)}, ${q(ii.sku_code)})`
  ).join(',\n');
  const sql =
`SET XACT_ABORT ON;
BEGIN TRAN;
DELETE FROM [exportImport].[dbo].[invoices] WHERE [file_name] = ${q(inv.file_name)};
INSERT INTO [exportImport].[dbo].[invoices] (id, file_name)
VALUES (${inv.invoice_id}, ${q(inv.file_name)});
INSERT INTO [exportImport].[dbo].[invoice_items]
  (id, invoice_id, line_no, item_name, unit, quantity, price, sku_code)
VALUES
${vals};
COMMIT;`;
  out.push({ json: { invoice_id: inv.invoice_id, file_name: inv.file_name, items_count: items.length, sql } });
}
return out;
